#!/bin/sh
# Builds the demo project for `pnpm demo`: "acme-shop", a made-up web shop (a TypeScript monorepo
# with a Prisma schema) with a short history of branches and merges, uncommitted work, and one
# deliberate type error, so every view has something to show. Generated by scripts, never a real
# project. Usage: make-project.sh <folder>
set -eu
root="$1/acme-shop"
rm -rf "$root"
mkdir -p "$root"
cd "$root"
git init -q -b main
w() { mkdir -p "$(dirname "$1")"; cat > "$1"; }
c() {
  GIT_AUTHOR_NAME="$2" GIT_AUTHOR_EMAIL="$3" GIT_AUTHOR_DATE="$4" \
  GIT_COMMITTER_NAME="$2" GIT_COMMITTER_EMAIL="$3" GIT_COMMITTER_DATE="$4" \
  git commit -q --allow-empty -m "$1"
}
m() {
  GIT_AUTHOR_NAME="$3" GIT_AUTHOR_EMAIL="$4" GIT_AUTHOR_DATE="$5" \
  GIT_COMMITTER_NAME="$3" GIT_COMMITTER_EMAIL="$4" GIT_COMMITTER_DATE="$5" \
  git merge -q --no-ff "$1" -m "$2"
}

w .gitignore <<'EOF'
node_modules
dist
EOF
w README.md <<'EOF'
# acme-shop

The Acme storefront: a web app, an API, and the shared money and catalog packages.
EOF
w package.json <<'EOF'
{ "name": "acme-shop", "private": true, "workspaces": ["apps/*", "packages/*"] }
EOF
w tsconfig.json <<'EOF'
{ "compilerOptions": { "strict": true, "target": "ES2022", "module": "ESNext", "moduleResolution": "Bundler", "paths": { "@web/*": ["./apps/web/src/*"] } } }
EOF
git add -A
c "chore: start the acme-shop monorepo" "Mia Chen" "mia.chen@acme.dev" "2026-09-28T10:12:00+02:00"
w packages/money/package.json <<'EOF'
{ "name": "@acme/money", "main": "src/index.ts" }
EOF
w packages/money/src/format.ts <<'EOF'
/** Formats an amount in cents as a price, like `€12.40`. */
export function formatPrice(cents: number, currency = "EUR"): string {
  return new Intl.NumberFormat("en-IE", { style: "currency", currency }).format(cents / 100);
}
EOF
w packages/money/src/index.ts <<'EOF'
export * from "./format";
export * from "./tax";
EOF
w packages/money/src/tax.ts <<'EOF'
import { formatPrice } from "./format";

export const VAT_RATE = 0.21;

/** The VAT on a net amount, rounded to the cent. */
export function vat(cents: number): number {
  return Math.round(cents * VAT_RATE);
}

export const showVat = (cents: number) => formatPrice(vat(cents));
EOF
git add -A
c "feat(money): format prices and work out vat" "Mia Chen" "mia.chen@acme.dev" "2026-09-29T14:40:00+02:00"
w packages/catalog/package.json <<'EOF'
{ "name": "@acme/catalog", "main": "src/index.ts" }
EOF
w packages/catalog/src/index.ts <<'EOF'
import { formatPrice } from "@acme/money";

export interface Product {
  id: string;
  name: string;
  priceCents: number;
  stock: number;
}

export const label = (product: Product) => `${product.name} · ${formatPrice(product.priceCents)}`;
export const inStock = (product: Product) => product.stock > 0;
EOF
git add -A
c "feat(catalog): products with labels and stock" "Leo Varga" "leo.varga@acme.dev" "2026-09-30T09:05:00+02:00"
git checkout -q -b feat/cart
w apps/web/src/cart/Cart.tsx <<'EOF'
import { formatPrice } from "@acme/money";
import { label } from "@acme/catalog";
import { total, type Line } from "./total";

export function Cart({ lines }: { lines: Line[] }) {
  return (
    <section>
      {lines.map((line) => (
        <p key={line.product.id}>{label(line.product)} × {line.quantity}</p>
      ))}
      <strong>{formatPrice(total(lines))}</strong>
    </section>
  );
}
EOF
w apps/web/src/cart/total.ts <<'EOF'
import { vat } from "@acme/money";
import type { Product } from "@acme/catalog";

export interface Line {
  product: Product;
  quantity: number;
}

/** The cart's total in cents, VAT included. */
export function total(lines: Line[]): number {
  const net = lines.reduce((sum, line) => sum + line.product.priceCents * line.quantity, 0);
  return net + vat(net);
}
EOF
git add -A
