w prisma/billing.prisma <<'EOF'
model Payment {
  id        String   @id @default(cuid())
  orderId   String   @unique
  order     Order    @relation(fields: [orderId], references: [id])
  amount    Int
  refunds   Refund[]
}

model Refund {
  id        String  @id @default(cuid())
  paymentId String
  payment   Payment @relation(fields: [paymentId], references: [id])
  amount    Int
  reason    String
}

model Invoice {
  id        String @id @default(cuid())
  number    String @unique
  paymentId String
  total     Int
}
EOF
w prisma/catalog.prisma <<'EOF'
model Product {
  id         String         @id @default(cuid())
  name       String
  priceCents Int
  categoryId String
  category   Category       @relation(fields: [categoryId], references: [id])
  variants   Variant[]
  images     ProductImage[]
  lines      OrderLine[]
}

model Variant {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id])
  sku       String  @unique
  stock     Int
}

model ProductImage {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id])
  url       String
}

model Category {
  id       String     @id @default(cuid())
  name     String
  parentId String?
  parent   Category?  @relation("Tree", fields: [parentId], references: [id])
  children Category[] @relation("Tree")
  products Product[]
}
EOF
w prisma/customers.prisma <<'EOF'
model Customer {
  id        String    @id @default(cuid())
  email     String    @unique
  name      String
  orders    Order[]
  addresses Address[]
}

model Address {
  id         String   @id @default(cuid())
  customerId String
  customer   Customer @relation(fields: [customerId], references: [id])
  street     String
  city       String
  country    String
}
EOF
w prisma/orders.prisma <<'EOF'
model Order {
  id         String      @id @default(cuid())
  customerId String
  customer   Customer    @relation(fields: [customerId], references: [id])
  lines      OrderLine[]
  payment    Payment?
  shipment   Shipment?
  createdAt  DateTime    @default(now())
}

model OrderLine {
  id        String  @id @default(cuid())
  orderId   String
  order     Order   @relation(fields: [orderId], references: [id])
  productId String
  product   Product @relation(fields: [productId], references: [id])
  quantity  Int
}

model Shipment {
  id        String  @id @default(cuid())
  orderId   String  @unique
  order     Order   @relation(fields: [orderId], references: [id])
  carrier   String
  tracking  String?
}
EOF
