git checkout -q -b fix/vat-rounding
w packages/money/src/tax.ts <<'EOF'
import { formatPrice } from "./format";

export const VAT_RATE = 0.21;

/** The VAT on a net amount, rounded half up to the cent. */
export function vat(cents: number): number {
  return Math.floor(cents * VAT_RATE + 0.5);
}

export const showVat = (cents: number) => formatPrice(vat(cents));
EOF
